def write_file(client_capabilities, path, content, roots, files):
    if not client_capabilities.get('fs', {}).get('writeTextFile', False):
        raise PermissionError('write capability not negotiated')
    if not path.startswith(tuple(root.rstrip('/') + '/' for root in roots)):
        raise PermissionError('outside workspace roots')
    files[path] = content
    return True
